/**
 * 简化版日期时间选择器 - 本地替代flatpickr
 */
(function () {
    // 简单的日期选择器实现
    window.flatpickr = function (selector, options) {
        // 默认配置
        const defaults = {
            enableTime: false,
            dateFormat: "Y-m-d",
            time_24hr: false,
            locale: "en"
        };

        // 合并选项
        const settings = Object.assign({}, defaults, options);

        // 查找匹配的元素
        let elements;
        if (typeof selector === 'string') {
            elements = document.querySelectorAll(selector);
        } else if (selector instanceof HTMLElement) {
            elements = [selector];
        } else if (selector instanceof NodeList || Array.isArray(selector)) {
            elements = selector;
        } else {
            elements = [];
        }

        // 为每个元素应用行为
        Array.from(elements).forEach(element => {
            // 存储原始输入框
            const input = element;

            // 设置输入框为只读，防止手动输入
            input.readOnly = true;

            // 创建日期选择器容器
            const pickerContainer = document.createElement('div');
            pickerContainer.className = 'date-picker-container';
            pickerContainer.style.display = 'none';
            pickerContainer.style.position = 'absolute';
            pickerContainer.style.backgroundColor = '#fff';
            pickerContainer.style.border = '1px solid #ddd';
            pickerContainer.style.borderRadius = '4px';
            pickerContainer.style.padding = '10px';
            pickerContainer.style.boxShadow = '0 0 10px rgba(0,0,0,0.1)';
            pickerContainer.style.zIndex = '9999';
            pickerContainer.style.width = '300px';

            // 添加到body
            document.body.appendChild(pickerContainer);

            // 创建日期选择UI
            function createDatePickerUI() {
                // 获取当前日期或输入框中的日期
                let currentDate = input.value ? new Date(input.value) : new Date();
                let currentYear = currentDate.getFullYear();
                let currentMonth = currentDate.getMonth();
                let currentDay = currentDate.getDate();
                let currentHour = currentDate.getHours();
                let currentMinute = currentDate.getMinutes();

                // 月份名称
                const monthNames = settings.locale === 'zh' ?
                    ["一月", "二月", "三月", "四月", "五月", "六月", "七月", "八月", "九月", "十月", "十一月", "十二月"] :
                    ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

                // 清空容器
                pickerContainer.innerHTML = '';

                // 创建头部 (月份选择和导航)
                const header = document.createElement('div');
                header.style.display = 'flex';
                header.style.justifyContent = 'space-between';
                header.style.marginBottom = '10px';

                // 上一月按钮
                const prevBtn = document.createElement('button');
                prevBtn.innerHTML = '&lt;';
                prevBtn.className = 'btn btn-sm btn-outline-secondary';
                prevBtn.onclick = () => {
                    currentMonth--;
                    if (currentMonth < 0) {
                        currentMonth = 11;
                        currentYear--;
                    }
                    createDatePickerUI();
                };

                // 月份和年份显示
                const monthYearDisplay = document.createElement('div');
                monthYearDisplay.textContent = `${monthNames[currentMonth]} ${currentYear}`;
                monthYearDisplay.style.fontWeight = 'bold';

                // 下一月按钮
                const nextBtn = document.createElement('button');
                nextBtn.innerHTML = '&gt;';
                nextBtn.className = 'btn btn-sm btn-outline-secondary';
                nextBtn.onclick = () => {
                    currentMonth++;
                    if (currentMonth > 11) {
                        currentMonth = 0;
                        currentYear++;
                    }
                    createDatePickerUI();
                };

                header.appendChild(prevBtn);
                header.appendChild(monthYearDisplay);
                header.appendChild(nextBtn);
                pickerContainer.appendChild(header);

                // 创建星期几标题行
                const weekdayNames = settings.locale === 'zh' ?
                    ["日", "一", "二", "三", "四", "五", "六"] :
                    ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

                const weekdaysRow = document.createElement('div');
                weekdaysRow.style.display = 'grid';
                weekdaysRow.style.gridTemplateColumns = 'repeat(7, 1fr)';
                weekdaysRow.style.textAlign = 'center';
                weekdaysRow.style.fontWeight = 'bold';
                weekdaysRow.style.marginBottom = '5px';

                weekdayNames.forEach(day => {
                    const dayElem = document.createElement('div');
                    dayElem.textContent = day;
                    weekdaysRow.appendChild(dayElem);
                });

                pickerContainer.appendChild(weekdaysRow);

                // 创建日历网格
                const calendarGrid = document.createElement('div');
                calendarGrid.style.display = 'grid';
                calendarGrid.style.gridTemplateColumns = 'repeat(7, 1fr)';
                calendarGrid.style.gap = '2px';

                // 获取月份的第一天是星期几
                const firstDayOfMonth = new Date(currentYear, currentMonth, 1).getDay();

                // 获取月份的天数
                const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

                // 填充日历前的空白
                for (let i = 0; i < firstDayOfMonth; i++) {
                    const emptyDay = document.createElement('div');
                    emptyDay.style.textAlign = 'center';
                    emptyDay.style.padding = '5px';
                    calendarGrid.appendChild(emptyDay);
                }

                // 填充日历天数
                for (let day = 1; day <= daysInMonth; day++) {
                    const dayElem = document.createElement('div');
                    dayElem.textContent = day;
                    dayElem.style.textAlign = 'center';
                    dayElem.style.padding = '5px';
                    dayElem.style.cursor = 'pointer';
                    dayElem.style.borderRadius = '4px';

                    // 高亮当前选择的日期
                    if (day === currentDay && new Date().getMonth() === currentMonth && new Date().getFullYear() === currentYear) {
                        dayElem.style.backgroundColor = '#007bff';
                        dayElem.style.color = 'white';
                    }

                    dayElem.onmouseover = () => {
                        if (!(day === currentDay && new Date().getMonth() === currentMonth && new Date().getFullYear() === currentYear)) {
                            dayElem.style.backgroundColor = '#f0f0f0';
                        }
                    };

                    dayElem.onmouseout = () => {
                        if (!(day === currentDay && new Date().getMonth() === currentMonth && new Date().getFullYear() === currentYear)) {
                            dayElem.style.backgroundColor = '';
                        }
                    };

                    dayElem.onclick = () => {
                        currentDay = day;
                        updateInputValue();

                        // 如果不需要时间选择，直接关闭选择器
                        if (!settings.enableTime) {
                            pickerContainer.style.display = 'none';
                        } else {
                            // 重新创建UI以高亮选中的日期
                            createDatePickerUI();
                        }
                    };

                    calendarGrid.appendChild(dayElem);
                }

                pickerContainer.appendChild(calendarGrid);

                // 添加时间选择器（如果启用）
                if (settings.enableTime) {
                    const timeContainer = document.createElement('div');
                    timeContainer.style.marginTop = '10px';
                    timeContainer.style.display = 'flex';
                    timeContainer.style.justifyContent = 'center';
                    timeContainer.style.alignItems = 'center';

                    // 小时选择
                    const hourSelect = document.createElement('select');
                    hourSelect.className = 'form-select form-select-sm';
                    hourSelect.style.width = 'auto';
                    hourSelect.style.marginRight = '5px';

                    for (let h = 0; h < 24; h++) {
                        const option = document.createElement('option');
                        option.value = h;
                        option.textContent = h < 10 ? `0${h}` : h;
                        if (h === currentHour) option.selected = true;
                        hourSelect.appendChild(option);
                    }

                    hourSelect.onchange = () => {
                        currentHour = parseInt(hourSelect.value);
                        updateInputValue();
                    };

                    // 分钟选择
                    const minuteSelect = document.createElement('select');
                    minuteSelect.className = 'form-select form-select-sm';
                    minuteSelect.style.width = 'auto';

                    for (let m = 0; m < 60; m += 5) {
                        const option = document.createElement('option');
                        option.value = m;
                        option.textContent = m < 10 ? `0${m}` : m;
                        if (m === Math.floor(currentMinute / 5) * 5) option.selected = true;
                        minuteSelect.appendChild(option);
                    }

                    minuteSelect.onchange = () => {
                        currentMinute = parseInt(minuteSelect.value);
                        updateInputValue();
                    };

                    const timeLabel = document.createElement('span');
                    timeLabel.textContent = settings.locale === 'zh' ? '时间: ' : 'Time: ';
                    timeLabel.style.marginRight = '5px';

                    const timeSeparator = document.createElement('span');
                    timeSeparator.textContent = ':';
                    timeSeparator.style.margin = '0 5px';

                    timeContainer.appendChild(timeLabel);
                    timeContainer.appendChild(hourSelect);
                    timeContainer.appendChild(timeSeparator);
                    timeContainer.appendChild(minuteSelect);

                    pickerContainer.appendChild(timeContainer);
                }

                // 添加按钮容器
                const buttonContainer = document.createElement('div');
                buttonContainer.style.marginTop = '10px';
                buttonContainer.style.display = 'flex';
                buttonContainer.style.justifyContent = 'flex-end';

                // 今天按钮
                const todayBtn = document.createElement('button');
                todayBtn.textContent = settings.locale === 'zh' ? '今天' : 'Today';
                todayBtn.className = 'btn btn-sm btn-outline-secondary';
                todayBtn.style.marginRight = '5px';
                todayBtn.onclick = () => {
                    const today = new Date();
                    currentYear = today.getFullYear();
                    currentMonth = today.getMonth();
                    currentDay = today.getDate();
                    currentHour = today.getHours();
                    currentMinute = today.getMinutes();
                    updateInputValue();
                    createDatePickerUI();
                };

                // 确定按钮
                const doneBtn = document.createElement('button');
                doneBtn.textContent = settings.locale === 'zh' ? '确定' : 'Done';
                doneBtn.className = 'btn btn-sm btn-primary';
                doneBtn.onclick = () => {
                    updateInputValue();
                    pickerContainer.style.display = 'none';
                };

                buttonContainer.appendChild(todayBtn);
                buttonContainer.appendChild(doneBtn);

                pickerContainer.appendChild(buttonContainer);

                // 更新输入框的值
                function updateInputValue() {
                    const year = currentYear;
                    const month = currentMonth + 1;
                    const day = currentDay;
                    const hour = currentHour;
                    const minute = currentMinute;

                    const formattedMonth = month < 10 ? `0${month}` : month;
                    const formattedDay = day < 10 ? `0${day}` : day;
                    const formattedHour = hour < 10 ? `0${hour}` : hour;
                    const formattedMinute = minute < 10 ? `0${minute}` : minute;

                    if (settings.enableTime) {
                        input.value = `${year}-${formattedMonth}-${formattedDay} ${formattedHour}:${formattedMinute}`;
                    } else {
                        input.value = `${year}-${formattedMonth}-${formattedDay}`;
                    }

                    // 触发change事件
                    const event = new Event('change');
                    input.dispatchEvent(event);
                }
            }

            // 添加点击事件
            input.addEventListener('click', function (e) {
                e.stopPropagation();

                // 定位选择器
                const rect = input.getBoundingClientRect();
                pickerContainer.style.top = `${rect.bottom + window.scrollY}px`;
                pickerContainer.style.left = `${rect.left + window.scrollX}px`;

                // 显示选择器
                pickerContainer.style.display = 'block';
                createDatePickerUI();
            });

            // 点击其他地方关闭选择器
            document.addEventListener('click', function (e) {
                if (e.target !== input && !pickerContainer.contains(e.target)) {
                    pickerContainer.style.display = 'none';
                }
            });
        });

        // 返回简单的API
        return {
            destroy: function () {
                // 清理函数
            },
            set: function (option, value) {
                // 设置选项
            }
        };
    };
})(); 